    "abstract": "The main problem The hospital provides eye-care services, but limited public awareness about its services and charity needs may restrict community donations and support. Target 1 — Create Awareness: Not many people know Albaseer eye hospital is a foundation hospital which is 100% free on need basis Make more people aware of: ·        What eye-care services the hospital is offering. ·        Free/subsidized treatment ·        Eye surgeries packages concise detail written in a Brocher Target 2 — Build Trust: Show donors where their support goes through: short videos and photos/social media campaigns ·        Patient stories Connect people emotionally with the hospital's work. ·        Use real patient/community stories , with informed consent. Photos and short videos ·        Hospital statistics (eye surgery in underdeveloped areas last year and this year) ·        Treatment/surgery impact on the society Target 3 — Generate Charity Support Encourage: ·        Monthly small donations campaigns ·        Find Corporate sponsorship",
